   288  /**
   289   * Runs through the given path (or query) segment and checks if
   290   * percent-encodings are correct. This function returns @c 0 on success
   291   * and @c -1 on error.
   292   */
   293  static int
   294  check_segment(const uint8_t *s, size_t length, size_t *segment_size) {
   295    size_t n = 0;
   296
   297    while (length) {
   298      if (*s == '%') {
   299        if (length < 2 || !(isxdigit(s[1]) && isxdigit(s[2])))
   300                return -1;
   301
   302        s += 2;
   303        length -= 2;
   304      }
   305
   306      ++s; ++n; --length;
   307    }
   308
   309    *segment_size = n;
   310
   311    return 0;
   312  }
