   380  /**
   381   * Checks if path segment @p s consists of one or two dots.
   382   */
   383  COAP_STATIC_INLINE int
   384  dots(const uint8_t *s, size_t len) {
   385    return len && *s == '.' && (len == 1 || (len == 2 && *(s+1) == '.'));
   386  }
