   547  COAP_STATIC_INLINE int
   548  is_unescaped_in_path(const uint8_t c) {
   549    return ( c >= 'A' && c <= 'Z' ) || ( c >= 'a' && c <= 'z' )
   550        || ( c >= '0' && c <= '9' ) || c == '-' || c == '.' || c == '_'
   551        || c == '~' || c == '!' || c == '$' || c == '\'' || c == '('
   552        || c == ')' || c == '*' || c == '+' || c == ',' || c == ';' || c=='='
   553        || c==':' || c=='@' || c == '&';
   554  }
   555
   556  COAP_STATIC_INLINE int
   557  is_unescaped_in_query(const uint8_t c) {
   558    return is_unescaped_in_path(c) || c=='/' || c=='?';
   559  }
