   660      while ((q = coap_option_next(&opt_iter))) {
   661        if (n++) {
   662          *s++ = '/';
   663        }
   664        uint16_t seg_len = coap_opt_length(q), i;
   665        const uint8_t *seg= coap_opt_value(q);
   666        for (i = 0; i < seg_len; i++) {
